'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'
import { useRouter } from 'next/navigation'
import { clsx } from 'clsx'
import { StarfieldBackground, GlassPanel, TypewriterText, Button } from '@/components/ui'
import { useGame } from '@/lib/game-context'
import { ShipType } from '@/lib/types'

const SHIPS: { id: ShipType; name: string; tagline: string; accent: 'terracotta' | 'nebula' | 'signal' }[] = [
  { id: 'spark', name: 'The Spark', tagline: 'Built for speed. Favored by vibe coders.', accent: 'terracotta' },
  { id: 'architect', name: 'The Architect', tagline: 'Built for precision. Favored by system thinkers.', accent: 'nebula' },
  { id: 'sentinel', name: 'The Sentinel', tagline: 'Built for resilience. Favored by security engineers.', accent: 'signal' },
]

const CRAWL_TEXT = `The year is 2026.

Software engineering has changed forever.

A revolution called "vibe coding" swept the industry \u2014 developers began talking to AI in natural language, building software at the speed of thought.

But speed came at a cost. AI-generated code carried 1.75x more bugs, 2.74x more security vulnerabilities. The galaxy\u2019s codebases grew fragile.

A new discipline emerged: Agentic Engineering \u2014 orchestrating fleets of AI agents with human oversight. The future belongs to those who can command them.

You are a rookie pilot. Your ship AI, ARIA, is your guide.

Your mission: journey from vibe coder to fleet commander.`

const shipBorderColors: Record<ShipType, string> = {
  spark: 'border-terracotta shadow-glow-terracotta',
  architect: 'border-nebula shadow-glow-nebula',
  sentinel: 'border-signal shadow-glow-signal',
}

const slideVariants = {
  enter: (direction: number) => ({
    x: direction > 0 ? 300 : -300,
    opacity: 0,
  }),
  center: {
    x: 0,
    opacity: 1,
  },
  exit: (direction: number) => ({
    x: direction > 0 ? -300 : 300,
    opacity: 0,
  }),
}

function ShipSVG({ type }: { type: ShipType }) {
  if (type === 'spark') {
    return (
      <svg viewBox="0 0 80 80" className="w-20 h-20 mx-auto mb-4">
        <polygon
          points="40,8 68,68 40,56 12,68"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          className="text-terracotta"
        />
        <line x1="40" y1="8" x2="40" y2="56" stroke="currentColor" strokeWidth="1" className="text-terracotta/50" />
      </svg>
    )
  }
  if (type === 'architect') {
    return (
      <svg viewBox="0 0 80 80" className="w-20 h-20 mx-auto mb-4">
        <polygon
          points="40,6 70,40 40,74 10,40"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          className="text-nebula"
        />
        <polygon
          points="40,20 56,40 40,60 24,40"
          fill="none"
          stroke="currentColor"
          strokeWidth="1"
          className="text-nebula/50"
        />
      </svg>
    )
  }
  return (
    <svg viewBox="0 0 80 80" className="w-20 h-20 mx-auto mb-4">
      <polygon
        points="40,6 72,22 72,58 40,74 8,58 8,22"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        className="text-signal"
      />
      <circle cx="40" cy="40" r="12" fill="none" stroke="currentColor" strokeWidth="1" className="text-signal/50" />
    </svg>
  )
}

function StepCallsign({
  callsign,
  setCallsign,
  isValid,
  onNext,
}: {
  callsign: string
  setCallsign: (v: string) => void
  isValid: boolean
  onNext: () => void
}) {
  return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] px-4">
      <GlassPanel className="w-full max-w-lg text-center" padding="lg">
        <h1 className="font-display uppercase tracking-wider text-xl mb-6 text-starlight">
          Pilot Registration
        </h1>

        <div className="mb-8 text-starlight-dim text-sm leading-relaxed min-h-[3rem]">
          <TypewriterText
            text="Every journey begins with a name, pilot. What should I call you?"
            speed={25}
          />
        </div>

        <input
          type="text"
          value={callsign}
          onChange={(e) => setCallsign(e.target.value.slice(0, 20))}
          placeholder="Enter your callsign..."
          className={clsx(
            'w-full bg-glass border border-glass-border rounded-xl px-4 py-3',
            'text-starlight font-mono text-center text-lg',
            'placeholder:text-starlight-dim/40',
            'focus:outline-none focus-visible:ring-2 focus-visible:ring-nebula/50 focus:border-glass-active',
            'transition-colors'
          )}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && isValid) onNext()
          }}
          autoFocus
        />

        <div className="mt-2 h-5 text-xs text-starlight-dim/60 font-mono">
          {callsign.length > 0 && !isValid && 'Callsign must be 2\u201320 characters'}
        </div>

        <div className="mt-4">
          <Button onClick={onNext} disabled={!isValid} size="lg">
            Next
          </Button>
        </div>
      </GlassPanel>
    </div>
  )
}

function StepShip({
  ship,
  setShip,
  onNext,
  onBack,
}: {
  ship: ShipType
  setShip: (v: ShipType) => void
  onNext: () => void
  onBack: () => void
}) {
  return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] px-4">
      <h1 className="font-display uppercase tracking-wider text-xl mb-8 text-starlight text-center">
        Select Your Vessel
      </h1>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 w-full max-w-3xl mb-8">
        {SHIPS.map((s) => {
          const isSelected = ship === s.id
          return (
            <GlassPanel
              key={s.id}
              hover
              glow={isSelected ? s.accent : undefined}
              className={clsx(
                'text-center cursor-pointer transition-all',
                isSelected && shipBorderColors[s.id]
              )}
              padding="md"
            >
              <div onClick={() => setShip(s.id)}>
                <ShipSVG type={s.id} />
                <h2 className={clsx(
                  'font-display uppercase tracking-wider text-base mb-2',
                  s.accent === 'terracotta' && 'text-terracotta',
                  s.accent === 'nebula' && 'text-nebula',
                  s.accent === 'signal' && 'text-signal'
                )}>
                  {s.name}
                </h2>
                <p className="text-starlight-dim text-sm leading-relaxed">
                  {s.tagline}
                </p>
              </div>
            </GlassPanel>
          )
        })}
      </div>

      <div className="flex gap-4">
        <Button variant="secondary" onClick={onBack} size="md">
          Back
        </Button>
        <Button onClick={onNext} size="md">
          Next
        </Button>
      </div>
    </div>
  )
}

function StepLaunch({ onBack, onLaunch }: { onBack: () => void; onLaunch: () => void }) {
  return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] px-4">
      <div
        className="w-full max-w-2xl overflow-hidden relative"
        style={{ perspective: '300px', height: '60vh' }}
      >
        {/* Top fade */}
        <div className="absolute top-0 left-0 right-0 h-24 bg-gradient-to-b from-void to-transparent z-10 pointer-events-none" />
        {/* Bottom fade */}
        <div className="absolute bottom-0 left-0 right-0 h-24 bg-gradient-to-t from-void to-transparent z-10 pointer-events-none" />

        <div
          className="text-crawl-wrapper absolute inset-0 flex items-start justify-center"
          style={{ transformStyle: 'preserve-3d' }}
        >
          <div
            className="text-crawl-content text-center px-8"
            style={{
              transform: 'rotateX(20deg)',
              animation: 'crawl 35s linear infinite',
            }}
          >
            {CRAWL_TEXT.split('\n\n').map((paragraph, i) => (
              <p
                key={i}
                className="text-starlight/90 text-base md:text-lg leading-relaxed mb-8 font-body"
              >
                {paragraph}
              </p>
            ))}
          </div>
        </div>
      </div>

      <div className="flex gap-4 mt-6">
        <Button variant="secondary" onClick={onBack} size="md">
          Back
        </Button>
        <Button
          onClick={onLaunch}
          size="lg"
          className="animate-pulse"
        >
          Launch
        </Button>
      </div>
    </div>
  )
}

export default function CreatePage() {
  const [step, setStep] = useState(1)
  const [direction, setDirection] = useState(1)
  const [callsign, setCallsign] = useState('')
  const [ship, setShip] = useState<ShipType>('spark')
  const { startNewGame } = useGame()
  const router = useRouter()

  const isValidCallsign = callsign.trim().length >= 2 && callsign.length <= 20

  const goNext = () => {
    setDirection(1)
    setStep((s) => s + 1)
  }

  const goBack = () => {
    setDirection(-1)
    setStep((s) => s - 1)
  }

  const handleLaunch = () => {
    startNewGame(callsign.trim(), ship)
    router.push('/cockpit')
  }

  return (
    <main className="relative min-h-screen">
      <StarfieldBackground />

      <AnimatePresence mode="wait" custom={direction}>
        {step === 1 && (
          <motion.div
            key="step-1"
            custom={direction}
            variants={slideVariants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{ type: 'spring', stiffness: 300, damping: 30 }}
          >
            <StepCallsign
              callsign={callsign}
              setCallsign={setCallsign}
              isValid={isValidCallsign}
              onNext={goNext}
            />
          </motion.div>
        )}

        {step === 2 && (
          <motion.div
            key="step-2"
            custom={direction}
            variants={slideVariants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{ type: 'spring', stiffness: 300, damping: 30 }}
          >
            <StepShip
              ship={ship}
              setShip={setShip}
              onNext={goNext}
              onBack={goBack}
            />
          </motion.div>
        )}

        {step === 3 && (
          <motion.div
            key="step-3"
            custom={direction}
            variants={slideVariants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{ type: 'spring', stiffness: 300, damping: 30 }}
          >
            <StepLaunch onBack={goBack} onLaunch={handleLaunch} />
          </motion.div>
        )}
      </AnimatePresence>

      <style jsx global>{`
        @keyframes crawl {
          from {
            transform: rotateX(20deg) translateY(100%);
          }
          to {
            transform: rotateX(20deg) translateY(-100%);
          }
        }
      `}</style>
    </main>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { motion, AnimatePresence } from 'motion/react'
import { clsx } from 'clsx'
import { useGame } from '@/lib/game-context'
import { StarfieldBackground, GlassPanel, StatGauge, XPBar, Button, TypewriterText } from '@/components/ui'
import { crewMembers } from '@/lib/data/crew'
import { STATS } from '@/lib/constants'
import { TOTAL_MISSIONS, planets } from '@/lib/data/planets'

const RANK_COLORS: Record<string, string> = {
  Cadet: '#c17147',
  Navigator: '#4a6fa5',
  Commander: '#6b9e78',
  Admiral: '#e8e0d4',
}

export default function CockpitPage() {
  const { state, loading, rank, totalStats, completedMissions } = useGame()
  const router = useRouter()
  const [showWelcome, setShowWelcome] = useState(false)

  useEffect(() => {
    if (!loading && !state) router.push('/')
  }, [loading, state, router])

  useEffect(() => {
    if (state && completedMissions === 0) {
      setShowWelcome(true)
    }
  }, [state, completedMissions])

  if (loading || !state) return null

  // Compute mission counts per act
  const actCounts = { 1: 0, 2: 0, 3: 0 }
  const actTotals = { 1: 0, 2: 0, 3: 0 }
  for (const planet of planets) {
    actTotals[planet.act] += planet.missionCount
    const completedForPlanet = Object.entries(state.missionProgress).filter(
      ([id, p]) => id.startsWith(planet.id) && p.status === 'completed'
    ).length
    actCounts[planet.act] += completedForPlanet
  }

  // Find next available planet
  const nextPlanet = planets.find((planet) => {
    const completedForPlanet = Object.entries(state.missionProgress).filter(
      ([id, p]) => id.startsWith(planet.id) && p.status === 'completed'
    ).length
    return completedForPlanet < planet.missionCount
  })

  const missionProgressPercent = (completedMissions / TOTAL_MISSIONS) * 100

  return (
    <div className="relative min-h-screen overflow-hidden">
      <StarfieldBackground speed={0.3} />

      <main className="relative z-10 max-w-5xl mx-auto px-4 py-8 space-y-6">
        {/* Top section: Player identity & rank */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: 'spring', stiffness: 100, damping: 15 }}
        >
          <GlassPanel padding="lg">
            <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-4">
              <h1 className="font-display text-3xl sm:text-4xl text-starlight tracking-wider">
                {state.callsign}
              </h1>
              <span
                className={clsx(
                  'inline-flex items-center px-3 py-1 rounded-full text-sm font-display uppercase tracking-widest border'
                )}
                style={{
                  color: RANK_COLORS[rank],
                  borderColor: `${RANK_COLORS[rank]}60`,
                  backgroundColor: `${RANK_COLORS[rank]}15`,
                }}
              >
                {rank}
              </span>
            </div>
            <XPBar totalStats={totalStats} rank={rank} />
          </GlassPanel>
        </motion.div>

        {/* Stats section: 2x2 grid (4-column on desktop) */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: 'spring', stiffness: 100, damping: 15, delay: 0.1 }}
        >
          <GlassPanel padding="md">
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              {STATS.map((stat) => (
                <StatGauge
                  key={stat}
                  stat={stat}
                  value={state.stats[stat]}
                />
              ))}
            </div>
          </GlassPanel>
        </motion.div>

        {/* Crew section */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: 'spring', stiffness: 100, damping: 15, delay: 0.2 }}
        >
          <GlassPanel padding="md">
            <h2 className="font-display text-lg uppercase tracking-widest text-nebula mb-4">
              Your Crew
            </h2>
            <div className="flex flex-wrap gap-6 justify-center sm:justify-start">
              {crewMembers.map((member) => {
                const recruited = state.crew.includes(member.id)
                return (
                  <div
                    key={member.id}
                    className="flex flex-col items-center gap-2 w-16"
                  >
                    <div
                      className={clsx(
                        'w-12 h-12 rounded-full flex items-center justify-center text-lg font-display border-2 transition-all',
                        recruited
                          ? 'border-opacity-60'
                          : 'border-glass-border opacity-30'
                      )}
                      style={
                        recruited
                          ? {
                              borderColor: member.color,
                              backgroundColor: `${member.color}20`,
                              color: member.color,
                            }
                          : undefined
                      }
                    >
                      {recruited ? member.name[0] : '?'}
                    </div>
                    <span
                      className={clsx(
                        'text-xs text-center font-mono leading-tight',
                        recruited ? 'text-starlight' : 'text-starlight-dim'
                      )}
                    >
                      {recruited ? member.name : 'Unknown'}
                    </span>
                  </div>
                )
              })}
            </div>
          </GlassPanel>
        </motion.div>

        {/* Mission log */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: 'spring', stiffness: 100, damping: 15, delay: 0.3 }}
        >
          <GlassPanel padding="md">
            <h2 className="font-display text-lg uppercase tracking-widest text-nebula mb-4">
              Mission Log
            </h2>

            <div className="space-y-3">
              {/* Current objective */}
              <p className="text-starlight text-sm">
                {nextPlanet
                  ? `Current objective: Complete ${nextPlanet.name} to progress`
                  : 'All missions complete!'}
              </p>

              {/* Mission progress bar */}
              <div className="space-y-1">
                <div className="flex justify-between items-center text-xs">
                  <span className="font-display uppercase tracking-wider text-signal">
                    Progress
                  </span>
                  <span className="font-mono text-starlight-dim">
                    {completedMissions}/{TOTAL_MISSIONS}
                  </span>
                </div>
                <div className="w-full h-2 bg-glass rounded-full overflow-hidden">
                  <motion.div
                    className="h-full rounded-full bg-gradient-to-r from-terracotta via-nebula to-signal"
                    initial={{ width: 0 }}
                    animate={{ width: `${missionProgressPercent}%` }}
                    transition={{ type: 'spring', stiffness: 100, damping: 15 }}
                  />
                </div>
              </div>

              {/* Act breakdown */}
              <p className="text-xs font-mono text-starlight-dim">
                Act 1: {actCounts[1]}/{actTotals[1]} | Act 2: {actCounts[2]}/{actTotals[2]} | Act 3: {actCounts[3]}/{actTotals[3]}
              </p>
            </div>
          </GlassPanel>
        </motion.div>

        {/* Navigation buttons */}
        <motion.div
          className="flex flex-col sm:flex-row gap-3 justify-center"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: 'spring', stiffness: 100, damping: 15, delay: 0.4 }}
        >
          <Button
            variant="primary"
            size="lg"
            onClick={() => router.push('/starmap')}
          >
            Open Star Map
          </Button>
          <Button
            variant="secondary"
            size="md"
            onClick={() => router.push('/crew')}
          >
            View Crew
          </Button>
          <Button
            variant="secondary"
            size="md"
            onClick={() => router.push('/inventory')}
          >
            View Inventory
          </Button>
        </motion.div>
      </main>

      {/* First-visit welcome overlay */}
      <AnimatePresence>
        {showWelcome && (
          <motion.div
            className="fixed inset-0 z-50 flex items-center justify-center p-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            {/* Backdrop */}
            <div className="absolute inset-0 bg-void/70 backdrop-blur-sm" />

            {/* Welcome panel */}
            <motion.div
              className="relative z-10 max-w-lg w-full"
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              transition={{ type: 'spring', stiffness: 200, damping: 20 }}
            >
              <GlassPanel padding="lg" glow="nebula">
                <div className="space-y-4">
                  <p className="text-starlight text-base leading-relaxed">
                    <TypewriterText
                      text={`Welcome aboard, ${state.callsign}. I'm ARIA, your ship's AI. Open the Star Map to begin your journey. Vibe World awaits.`}
                      speed={25}
                    />
                  </p>
                  <div className="flex justify-center pt-2">
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => setShowWelcome(false)}
                    >
                      Dismiss
                    </Button>
                  </div>
                </div>
              </GlassPanel>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

